#!/usr/bin/env python3
"""Minimal ANSI terminal emulator to render captured PTY output."""
import re, sys

class Term:
    def __init__(self, rows=24, cols=80):
        self.rows = rows; self.cols = cols
        self.grid = [[" "] * cols for _ in range(rows)]
        self.attr = [[None] * cols for _ in range(rows)]
        self.r = 0; self.c = 0
        self.cur_attr = []
        self.show_cursor = True
    def put(self, ch):
        if 0 <= self.r < self.rows and 0 <= self.c < self.cols:
            self.grid[self.r][self.c] = ch
            self.attr[self.r][self.c] = tuple(self.cur_attr)
        self.c += 1
        if self.c >= self.cols:
            self.c = self.cols - 1  # no autowrap handling needed mostly
    def feed(self, data):
        i = 0; n = len(data)
        while i < n:
            ch = data[i]
            if ch == "\x1b":
                m = re.match(r"\x1b\[([0-9;?]*)([@-~])", data[i:])
                if m:
                    params, cmd = m.group(1), m.group(2)
                    self.handle_csi(params, cmd)
                    i += m.end(); continue
                if data[i:i+2] == "\x1bM":
                    i += 2; continue
                i += 1; continue
            elif ch == "\r": self.c = 0
            elif ch == "\n":
                self.r = min(self.r + 1, self.rows - 1)
            elif ch == "\b": self.c = max(0, self.c - 1)
            elif ch == "\x07": pass
            elif ord(ch) < 32: pass
            else:
                self.put(ch)
            i += 1
    def handle_csi(self, params, cmd):
        parts = params.split(";") if params else [""]
        def num(k, default=1):
            try:
                v = int(parts[k].lstrip("?"))
                return v if v > 0 else default
            except (ValueError, IndexError):
                return default
        if cmd == "H" or cmd == "f":
            self.r = num(0) - 1; self.c = num(1) - 1
            self.r = max(0, min(self.r, self.rows-1)); self.c = max(0, min(self.c, self.cols-1))
        elif cmd == "A": self.r = max(0, self.r - num(0))
        elif cmd == "B": self.r = min(self.rows-1, self.r + num(0))
        elif cmd == "C": self.c = min(self.cols-1, self.c + num(0))
        elif cmd == "D": self.c = max(0, self.c - num(0))
        elif cmd == "G": self.c = max(0, min(num(0)-1, self.cols-1))
        elif cmd == "d": self.r = max(0, min(num(0)-1, self.rows-1))
        elif cmd == "J":
            mode = num(0, 0)
            if mode == 2 or mode == 3:
                self.grid = [[" "]*self.cols for _ in range(self.rows)]
                self.attr = [[None]*self.cols for _ in range(self.rows)]
            elif mode == 0:
                for cc in range(self.c, self.cols):
                    self.grid[self.r][cc] = " "; self.attr[self.r][cc] = None
                for rr in range(self.r+1, self.rows):
                    self.grid[rr] = [" "]*self.cols; self.attr[rr] = [None]*self.cols
            elif mode == 1:
                for rr in range(0, self.r):
                    self.grid[rr] = [" "]*self.cols; self.attr[rr] = [None]*self.cols
                for cc in range(0, self.c+1):
                    self.grid[self.r][cc] = " "; self.attr[self.r][cc] = None
        elif cmd == "K":
            mode = num(0, 0)
            if mode == 0:
                for cc in range(self.c, self.cols):
                    self.grid[self.r][cc] = " "; self.attr[self.r][cc] = None
            elif mode == 1:
                for cc in range(0, self.c+1):
                    self.grid[self.r][cc] = " "; self.attr[self.r][cc] = None
            elif mode == 2:
                self.grid[self.r] = [" "]*self.cols; self.attr[self.r] = [None]*self.cols
        elif cmd == "m":
            vals = []
            for p in parts:
                try: vals.append(int(p))
                except ValueError: vals.append(0)
            if not vals: vals = [0]
            self.cur_attr = vals
        elif cmd == "h" and params == "?25": self.show_cursor = True
        elif cmd == "l" and params == "?25": self.show_cursor = False
    def render(self, with_attr=False):
        lines = []
        for ri, row in enumerate(self.grid):
            line = "".join(row).rstrip()
            lines.append(line)
        return "\n".join(lines)
    def render_attr(self):
        out = []
        for ri, row in enumerate(self.grid):
            cur = None; seg = ""
            line = []
            for ci, ch in enumerate(row):
                a = self.attr[ri][ci]
                if a != cur:
                    if seg: line.append(f"[{cur}]{seg}")
                    cur = a; seg = ch
                else:
                    seg += ch
            if seg: line.append(f"[{cur}]{seg}")
            out.append("".join(line).rstrip())
        return "\n".join(out)

if __name__ == "__main__":
    data = open(sys.argv[1], "rb").read().decode("utf-8", errors="replace")
    rows = int(sys.argv[2]) if len(sys.argv) > 2 else 24
    cols = int(sys.argv[3]) if len(sys.argv) > 3 else 80
    t = Term(rows, cols)
    t.feed(data)
    if len(sys.argv) > 4 and sys.argv[4] == "attr":
        print(t.render_attr())
    else:
        print(t.render())

