#!/usr/bin/env python3
"""Interactive PTY driver for ./executable using vt.Term."""
import os, pty, time, select, fcntl, termios, struct, signal, sys
from vt import Term

class Session:
    def __init__(self, args, rows=24, cols=80):
        self.rows, self.cols = rows, cols
        self.pid, self.fd = pty.fork()
        if self.pid == 0:
            os.execv("./executable", ["./executable"] + args)
        fcntl.ioctl(self.fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
        self.term = Term(rows, cols)
        self.alive = True
    def pump(self, duration=0.3):
        end = time.time() + duration
        data = b""
        while time.time() < end:
            r, _, _ = select.select([self.fd], [], [], 0.05)
            if r:
                try:
                    chunk = os.read(self.fd, 65536)
                except OSError:
                    self.alive = False
                    break
                if not chunk:
                    self.alive = False
                    break
                data += chunk
        if data:
            self.term.feed(data.decode("utf-8", errors="replace"))
        return data
    def send(self, s, settle=0.1):
        os.write(self.fd, s.encode() if isinstance(s, str) else s)
        return self.pump(settle)
    def screen(self):
        return self.term.render()
    def screen_attr(self):
        return self.term.render_attr()
    def lesson_text(self):
        # lesson line is row 7 (index 6) between borders
        lines = self.term.render().split("\n")
        for ln in lines:
            if "│" in ln and not any(k in ln for k in ("Lesson", "need", "ngrrram", "─")):
                inner = ln.split("│")[1] if ln.count("│") >= 2 else ""
                if inner.strip() and not any(b in inner for b in "┌┐└┘┬┴├┤"):
                    return inner.strip()
        return ""
    def close(self):
        try:
            os.kill(self.pid, signal.SIGKILL)
            os.waitpid(self.pid, 0)
        except OSError:
            pass
    def exit_status(self):
        pid, status = os.waitpid(self.pid, os.WNOHANG)
        if pid == 0:
            return None
        return os.waitstatus_to_exitcode(status)

if __name__ == "__main__":
    s = Session(sys.argv[1:])
    s.pump(0.6)
    print(s.screen())
    s.close()

